-- Generated by Robert 5e0e9520f580bed160390064d8691e0b95abbb2c controlled dry-run cycle.
-- No ORM initializer used; synthetic fixture paths normalized.
PRAGMA foreign_keys=OFF;
BEGIN;
CREATE TABLE actor_permissions (
  permission_id TEXT PRIMARY KEY,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  actor_id TEXT NOT NULL REFERENCES actors(actor_id) ON DELETE CASCADE,
  trust_level TEXT NOT NULL CHECK (trust_level IN ('trusted_trigger', 'accepted_context', 'ignored')),
  source TEXT NOT NULL,
  checked_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  UNIQUE(repo_id, actor_id, source)
);
CREATE TABLE actors (
  actor_id TEXT PRIMARY KEY,
  login TEXT NOT NULL UNIQUE,
  actor_kind TEXT NOT NULL DEFAULT 'user',
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE agent_runs (
  run_id TEXT PRIMARY KEY,
  status TEXT NOT NULL CHECK (status IN ('running', 'completed', 'failed', 'skipped')),
  started_at TEXT NOT NULL,
  finished_at TEXT,
  config_path TEXT,
  dry_run INTEGER NOT NULL DEFAULT 0 CHECK (dry_run IN (0, 1)),
  summary_json TEXT NOT NULL DEFAULT '{}',
  error_json TEXT
);
CREATE TABLE artifacts (
  artifact_id TEXT PRIMARY KEY,
  task_id TEXT REFERENCES tasks(task_id) ON DELETE CASCADE,
  attempt_id TEXT REFERENCES attempts(attempt_id) ON DELETE SET NULL,
  artifact_type TEXT NOT NULL,
  path TEXT NOT NULL,
  sha256 TEXT,
  bytes INTEGER,
  created_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE attempts (
  attempt_id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL REFERENCES tasks(task_id) ON DELETE CASCADE,
  attempt_no INTEGER NOT NULL CHECK (attempt_no >= 1),
  status TEXT NOT NULL CHECK (status IN ('prepared', 'running', 'completed', 'failed', 'stale', 'canceled')),
  worktree_path TEXT,
  branch_name TEXT,
  started_at TEXT,
  heartbeat_at TEXT,
  finished_at TEXT,
  failure_json TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  UNIQUE(task_id, attempt_no)
);
CREATE TABLE audit_events (
  audit_id TEXT PRIMARY KEY,
  repo_id TEXT REFERENCES repos(repo_id) ON DELETE SET NULL,
  workstream_id TEXT REFERENCES workstreams(workstream_id) ON DELETE SET NULL,
  task_id TEXT REFERENCES tasks(task_id) ON DELETE SET NULL,
  event_type TEXT NOT NULL,
  created_at TEXT NOT NULL,
  payload_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE daemon_events (
  daemon_event_id TEXT PRIMARY KEY,
  daemon_run_id TEXT NOT NULL REFERENCES daemon_runs(daemon_run_id) ON DELETE CASCADE,
  event_type TEXT NOT NULL,
  status TEXT NOT NULL,
  created_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE daemon_runs (
  daemon_run_id TEXT PRIMARY KEY,
  status TEXT NOT NULL CHECK (status IN ('running', 'stopped', 'failed', 'replaced')),
  owner_id TEXT NOT NULL,
  config_path TEXT NOT NULL,
  started_at TEXT NOT NULL,
  finished_at TEXT,
  summary_json TEXT NOT NULL DEFAULT '{}',
  error_json TEXT
);
CREATE TABLE execution_fact_receipts (
  subject_type TEXT NOT NULL,
  subject_id TEXT NOT NULL,
  fact_id TEXT NOT NULL,
  evidence_json TEXT,
  PRIMARY KEY(subject_type,subject_id,fact_id)
);
CREATE TABLE execution_migrations (
  migration_id TEXT PRIMARY KEY,
  source_fingerprint TEXT NOT NULL UNIQUE,
  applied_at TEXT NOT NULL,
  snapshot_json TEXT NOT NULL,
  mappings_json TEXT NOT NULL
);
CREATE TABLE execution_pending_facts (
  source_signal_id TEXT PRIMARY KEY,
  subject_type TEXT NOT NULL,
  subject_id TEXT NOT NULL,
  topic TEXT NOT NULL,
  dedupe_key TEXT NOT NULL,
  fact_id TEXT NOT NULL,
  disposition TEXT NOT NULL,
  repo_id TEXT NOT NULL,
  task_id TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  not_before_at TEXT NOT NULL,
  consumed_at TEXT,
  resolution_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE execution_subjects (
  subject_type TEXT NOT NULL CHECK (subject_type IN ('task','remediation_episode')),
  subject_id TEXT NOT NULL,
  workflow_kind TEXT NOT NULL CHECK (workflow_kind IN ('human_request','pr_remediation')),
  binding_status TEXT NOT NULL CHECK (binding_status IN ('active','terminal','attention')),
  recovery_attempts INTEGER NOT NULL DEFAULT 0 CHECK (recovery_attempts BETWEEN 0 AND 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  terminal_at TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY(subject_type,subject_id)
);
CREATE TABLE github_actions (
  action_id TEXT PRIMARY KEY,
  result_id TEXT REFERENCES worker_results(result_id) ON DELETE SET NULL,
  task_id TEXT NOT NULL REFERENCES tasks(task_id) ON DELETE CASCADE,
  action_type TEXT NOT NULL,
  target_url TEXT,
  external_id TEXT,
  audit_status TEXT NOT NULL DEFAULT 'pending' CHECK (audit_status IN ('pending', 'accepted', 'policy_violation', 'failed')),
  publish_status TEXT NOT NULL DEFAULT 'not_published' CHECK (publish_status IN ('not_published', 'published', 'skipped')),
  created_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE github_control_children (
  child_id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL,
  lane TEXT NOT NULL,
  identity_json TEXT NOT NULL,
  status TEXT NOT NULL
);
CREATE TABLE github_events (
  event_id TEXT PRIMARY KEY,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  source_id TEXT NOT NULL REFERENCES github_sources(source_id) ON DELETE CASCADE,
  event_fingerprint TEXT NOT NULL UNIQUE,
  event_type TEXT NOT NULL,
  actor_kind TEXT NOT NULL DEFAULT 'github_user',
  actor_login TEXT,
  author_association TEXT,
  authorization_status TEXT NOT NULL DEFAULT 'pending',
  event_at TEXT NOT NULL,
  payload_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE github_read_cache (
  scope TEXT NOT NULL,
  cache_key TEXT NOT NULL,
  version TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  expires_at REAL NOT NULL,
  PRIMARY KEY(scope, cache_key)
);
CREATE TABLE github_scan_batches (
  batch_id TEXT PRIMARY KEY,
  repo_id TEXT NOT NULL,
  context_digest TEXT NOT NULL,
  raw_events_json TEXT NOT NULL,
  complete_sources_json TEXT NOT NULL DEFAULT '[]',
  retry_count INTEGER NOT NULL DEFAULT 0,
  attention_reason TEXT,
  created_at REAL NOT NULL,
  retry_at REAL NOT NULL,
  completed_at REAL
);
CREATE TABLE github_scan_reads (
  repo_id TEXT NOT NULL,
  command_key TEXT NOT NULL,
  response_json TEXT,
  observed_at REAL NOT NULL,
  PRIMARY KEY(repo_id,command_key)
);
CREATE TABLE github_sources (
  source_id TEXT PRIMARY KEY,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  source_key TEXT NOT NULL UNIQUE,
  source_type TEXT NOT NULL CHECK (source_type IN ('issue', 'pull_request')),
  number INTEGER NOT NULL,
  html_url TEXT,
  title TEXT NOT NULL DEFAULT '',
  state TEXT NOT NULL DEFAULT 'open',
  author_login TEXT,
  source_updated_at TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE knowledge_candidates (
  candidate_id TEXT PRIMARY KEY,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  summary TEXT NOT NULL,
  prompt_text TEXT NOT NULL,
  candidate_type TEXT NOT NULL DEFAULT 'rule' CHECK (candidate_type IN ('rule', 'anti_pattern', 'route_hint', 'verification_hint')),
  source_memory_ids_json TEXT NOT NULL DEFAULT '[]',
  evidence_json TEXT NOT NULL DEFAULT '[]',
  confidence TEXT NOT NULL DEFAULT 'medium' CHECK (confidence IN ('high', 'medium', 'low')),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'superseded')),
  created_at TEXT NOT NULL,
  reviewed_at TEXT,
  reviewer TEXT,
  review_note TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  UNIQUE(repo_id, title, source_memory_ids_json)
);
CREATE TABLE leases (
  lease_id TEXT PRIMARY KEY,
  resource_type TEXT NOT NULL,
  resource_key TEXT NOT NULL,
  owner_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('active', 'released', 'expired', 'stolen')),
  acquired_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  heartbeat_at TEXT NOT NULL,
  released_at TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE notifications (
  notification_id TEXT PRIMARY KEY,
  task_id TEXT REFERENCES tasks(task_id) ON DELETE SET NULL,
  notification_type TEXT NOT NULL,
  channel TEXT NOT NULL DEFAULT 'local',
  status TEXT NOT NULL,
  created_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE pr_ci_observations (
  observation_id TEXT PRIMARY KEY,
  episode_id TEXT NOT NULL REFERENCES pr_remediation_episodes(episode_id) ON DELETE CASCADE,
  source_kind TEXT NOT NULL CHECK (source_kind IN ('workflow_run', 'check_run')),
  external_id TEXT NOT NULL,
  attempt_no INTEGER NOT NULL DEFAULT 1 CHECK (attempt_no >= 1),
  check_name TEXT NOT NULL,
  status TEXT NOT NULL,
  conclusion TEXT,
  details_url TEXT,
  completed_at TEXT,
  failure_signature TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  UNIQUE(source_kind, external_id, attempt_no)
);
CREATE TABLE pr_remediation_episodes (
  episode_id TEXT PRIMARY KEY,
  workstream_id TEXT NOT NULL REFERENCES workstreams(workstream_id) ON DELETE CASCADE,
  episode_kind TEXT NOT NULL CHECK (episode_kind IN ('ci', 'merge_conflict')),
  subject_key TEXT NOT NULL,
  observed_head_sha TEXT NOT NULL,
  observed_base_sha TEXT NOT NULL,
  result_head_sha TEXT,
  status TEXT NOT NULL CHECK (status IN ('open', 'queued', 'remediating', 'waiting_for_signal', 'resolved', 'exhausted', 'superseded', 'canceled')),
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  failure_signature TEXT,
  first_seen_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  terminal_at TEXT,
  last_task_id TEXT REFERENCES tasks(task_id) ON DELETE SET NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  UNIQUE(workstream_id, episode_kind, subject_key)
);
CREATE TABLE project_memory_entries (
  memory_id TEXT PRIMARY KEY,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  memory_thread_key TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'context',
  title TEXT NOT NULL,
  short_summary TEXT NOT NULL,
  long_summary TEXT NOT NULL DEFAULT '',
  confidence TEXT NOT NULL DEFAULT 'medium' CHECK (confidence IN ('high', 'medium', 'low')),
  source_task_id TEXT REFERENCES tasks(task_id) ON DELETE SET NULL,
  source_result_id TEXT REFERENCES worker_results(result_id) ON DELETE SET NULL,
  current_revision_id TEXT,
  revision_count INTEGER NOT NULL DEFAULT 0 CHECK (revision_count >= 0),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  last_used_at TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  UNIQUE(repo_id, memory_thread_key, kind, title)
);
CREATE TABLE project_memory_revisions (
  revision_id TEXT PRIMARY KEY,
  memory_id TEXT NOT NULL REFERENCES project_memory_entries(memory_id) ON DELETE CASCADE,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  result_id TEXT REFERENCES worker_results(result_id) ON DELETE SET NULL,
  task_id TEXT REFERENCES tasks(task_id) ON DELETE SET NULL,
  attempt_id TEXT REFERENCES attempts(attempt_id) ON DELETE SET NULL,
  operation TEXT NOT NULL DEFAULT 'upsert',
  title TEXT NOT NULL,
  short_summary TEXT NOT NULL,
  long_summary TEXT NOT NULL DEFAULT '',
  payload_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL
);
CREATE TABLE project_memory_terms (
  memory_id TEXT NOT NULL REFERENCES project_memory_entries(memory_id) ON DELETE CASCADE,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  term_type TEXT NOT NULL,
  term_value TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY(memory_id, term_type, term_value)
);
CREATE TABLE publication_intents (
  publication_id TEXT PRIMARY KEY,
  action_id TEXT NOT NULL UNIQUE
    REFERENCES github_actions(action_id) ON DELETE CASCADE,
  idempotency_key TEXT NOT NULL UNIQUE,
  request_fingerprint TEXT NOT NULL,
  status TEXT NOT NULL
    CHECK (status IN (
      'prepared', 'executing', 'published', 'confirmed_absent',
      'failed', 'attention'
    )),
  started_at TEXT,
  finished_at TEXT,
  remote_evidence_json TEXT NOT NULL DEFAULT '{}',
  error_json TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE repos (
  repo_id TEXT PRIMARY KEY,
  full_name TEXT NOT NULL UNIQUE,
  github_account TEXT NOT NULL,
  default_base_branch TEXT NOT NULL,
  repo_root TEXT NOT NULL,
  worktree_root TEXT NOT NULL,
  enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)),
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE review_process_pool (
  singleton INTEGER PRIMARY KEY CHECK(singleton=1),
  max_concurrency INTEGER NOT NULL CHECK(max_concurrency>0)
);
CREATE TABLE review_runs (
  run_id TEXT PRIMARY KEY,
  round_id TEXT NOT NULL REFERENCES review_sessions(round_id),
  stage TEXT NOT NULL CHECK(stage IN ('prepare','review','synthesis')),
  worker_id TEXT NOT NULL,
  model TEXT,
  attempt_no INTEGER NOT NULL,
  owner_attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),
  status TEXT NOT NULL,
  output_dir TEXT NOT NULL UNIQUE,
  prompt_sha256 TEXT NOT NULL,
  slot_reserved INTEGER NOT NULL DEFAULT 0,
  started_at TEXT,
  dispatch_json TEXT,
  artifact_json TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(round_id, stage, worker_id, attempt_no)
);
CREATE TABLE review_sessions (
  round_id TEXT PRIMARY KEY,
  repo TEXT NOT NULL,
  pr_number INTEGER NOT NULL,
  workstream_id TEXT NOT NULL,
  trigger_fingerprint TEXT NOT NULL,
  task_id TEXT UNIQUE REFERENCES tasks(task_id),
  status TEXT NOT NULL DEFAULT 'queued',
  request_json TEXT NOT NULL,
  manifest_json TEXT,
  report_path TEXT,
  report_sha256 TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(repo, pr_number, trigger_fingerprint)
);
CREATE TABLE route_decisions (
  route_decision_id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL REFERENCES tasks(task_id) ON DELETE CASCADE,
  route_id TEXT NOT NULL,
  expected_output TEXT NOT NULL,
  allowed_github_actions_json TEXT NOT NULL DEFAULT '[]',
  required_skills_json TEXT NOT NULL DEFAULT '[]',
  recommended_skills_json TEXT NOT NULL DEFAULT '[]',
  confidence TEXT NOT NULL CHECK (confidence IN ('high', 'medium', 'low')),
  created_at TEXT NOT NULL
);
CREATE TABLE run_repo_steps (
  step_id TEXT PRIMARY KEY,
  run_id TEXT NOT NULL REFERENCES agent_runs(run_id) ON DELETE CASCADE,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  step_key TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'succeeded', 'failed', 'skipped')),
  started_at TEXT,
  finished_at TEXT,
  output_json TEXT,
  error_json TEXT,
  UNIQUE(run_id, repo_id, step_key)
);
CREATE TABLE run_steps (
  step_id TEXT PRIMARY KEY,
  run_id TEXT NOT NULL REFERENCES agent_runs(run_id) ON DELETE CASCADE,
  step_key TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'succeeded', 'failed', 'skipped')),
  started_at TEXT,
  finished_at TEXT,
  output_json TEXT,
  error_json TEXT,
  UNIQUE(run_id, step_key)
);
CREATE TABLE runtime_knowledge (
  knowledge_id TEXT PRIMARY KEY,
  candidate_id TEXT REFERENCES knowledge_candidates(candidate_id) ON DELETE SET NULL,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  scope_type TEXT NOT NULL CHECK (scope_type IN ('global', 'route', 'path', 'symbol', 'workstream')),
  scope_value TEXT NOT NULL DEFAULT '',
  title TEXT NOT NULL,
  prompt_text TEXT NOT NULL,
  retrieval_boost_json TEXT NOT NULL DEFAULT '{}',
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  approved_by TEXT NOT NULL,
  approved_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE schema_migrations (
  version INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  checksum TEXT NOT NULL,
  applied_at TEXT NOT NULL
);
CREATE TABLE supervision_checkpoints (
  scope_type TEXT NOT NULL,
  scope_id TEXT NOT NULL,
  rule_id TEXT NOT NULL,
  lineage_key TEXT NOT NULL DEFAULT '',
  classification TEXT CHECK (classification IN ('healthy','expected_wait','suspect','confirmed','unobservable')),
  reason_code TEXT,
  evidence_json TEXT NOT NULL DEFAULT '{}',
  progress_token TEXT,
  last_progress_at TEXT,
  eligible_since TEXT,
  next_check_at TEXT,
  updated_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY (scope_type, scope_id, rule_id)
);
CREATE TABLE supervision_incidents (
  incident_id TEXT PRIMARY KEY,
  scope_type TEXT NOT NULL,
  scope_id TEXT NOT NULL,
  rule_id TEXT NOT NULL,
  lineage_key TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL CHECK (status IN ('open','diagnosing','recovering','verifying','needs_attention','resolved','dismissed')),
  reason_code TEXT NOT NULL,
  severity TEXT NOT NULL,
  evidence_json TEXT NOT NULL,
  expected_progress_json TEXT NOT NULL,
  first_observed_at TEXT NOT NULL,
  last_observed_at TEXT NOT NULL,
  next_check_at TEXT,
  prior_incident_id TEXT REFERENCES supervision_incidents(incident_id) ON DELETE SET NULL,
  resolved_at TEXT,
  resolved_by TEXT,
  resolution_evidence_json TEXT NOT NULL DEFAULT '{}',
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE supervision_recovery_actions (
  action_id TEXT PRIMARY KEY,
  incident_id TEXT REFERENCES supervision_incidents(incident_id),
  lineage_key TEXT NOT NULL,
  scope_type TEXT NOT NULL,
  scope_id TEXT NOT NULL,
  stage_family TEXT NOT NULL,
  action_kind TEXT NOT NULL,
  recovery_ordinal INTEGER NOT NULL CHECK (recovery_ordinal > 0),
  idempotency_key TEXT NOT NULL UNIQUE,
  target_id TEXT NOT NULL,
  target_generation TEXT NOT NULL,
  policy_version TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('proposed','requested','applying','observing','succeeded','failed','rejected','unknown')),
  budget_cost INTEGER NOT NULL DEFAULT 0 CHECK (budget_cost >= 0),
  claim_owner TEXT,
  claim_generation INTEGER NOT NULL DEFAULT 0 CHECK (claim_generation >= 0),
  claim_expires_at TEXT,
  preconditions_json TEXT NOT NULL DEFAULT '{}',
  expected_progress_json TEXT NOT NULL DEFAULT '{}',
  receipt_json TEXT NOT NULL DEFAULT '{}',
  verification_evidence_json TEXT NOT NULL DEFAULT '{}',
  created_at TEXT NOT NULL,
  started_at TEXT,
  finished_at TEXT,
  next_check_at TEXT,
  UNIQUE (lineage_key, scope_type, scope_id, action_kind, recovery_ordinal)
);
CREATE TABLE task_events (
  task_id TEXT NOT NULL REFERENCES tasks(task_id) ON DELETE CASCADE,
  event_id TEXT NOT NULL REFERENCES github_events(event_id) ON DELETE CASCADE,
  relationship TEXT NOT NULL CHECK (relationship IN ('trigger', 'pending', 'consumed', 'context')),
  created_at TEXT NOT NULL,
  PRIMARY KEY(task_id, event_id)
);
CREATE TABLE tasks (
  task_id TEXT PRIMARY KEY,
  workstream_id TEXT NOT NULL REFERENCES workstreams(workstream_id) ON DELETE CASCADE,
  task_kind TEXT NOT NULL DEFAULT 'human_request' CHECK (task_kind IN ('human_request', 'ci_remediation', 'merge_conflict_remediation')),
  lifecycle TEXT NOT NULL CHECK (lifecycle IN ('detected', 'authorized', 'classified', 'queued', 'running', 'completed', 'waiting_for_user', 'failed', 'canceled', 'ignored')),
  parent_task_id TEXT REFERENCES tasks(task_id) ON DELETE SET NULL,
  priority TEXT NOT NULL DEFAULT 'P2',
  routing_mode TEXT NOT NULL DEFAULT 'auto' CHECK (routing_mode IN ('auto', 'manual')),
  requested_worker TEXT,
  route_id TEXT,
  expected_output TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  CHECK ((routing_mode = 'auto' AND requested_worker IS NULL)
      OR (routing_mode = 'manual' AND requested_worker IS NOT NULL))
);
CREATE TABLE vote_runs (
  run_id TEXT PRIMARY KEY,
  round_id TEXT NOT NULL REFERENCES vote_sessions(round_id),
  stage TEXT NOT NULL CHECK(stage IN ('prepare','vote','synthesis')),
  worker_id TEXT NOT NULL,
  model TEXT,
  attempt_no INTEGER NOT NULL,
  owner_attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id),
  status TEXT NOT NULL,
  output_dir TEXT NOT NULL UNIQUE,
  prompt_sha256 TEXT NOT NULL,
  slot_reserved INTEGER NOT NULL DEFAULT 0,
  started_at TEXT,
  dispatch_json TEXT,
  artifact_json TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(round_id, stage, worker_id, attempt_no)
);
CREATE TABLE vote_sessions (
  round_id TEXT PRIMARY KEY,
  repo TEXT NOT NULL,
  number INTEGER NOT NULL,
  source_type TEXT NOT NULL,
  workstream_id TEXT NOT NULL,
  trigger_fingerprint TEXT NOT NULL,
  task_id TEXT UNIQUE REFERENCES tasks(task_id),
  status TEXT NOT NULL DEFAULT 'queued',
  request_json TEXT NOT NULL,
  manifest_json TEXT,
  report_path TEXT,
  report_sha256 TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(repo, source_type, number, trigger_fingerprint)
);
CREATE TABLE wakeups (
  wakeup_id TEXT PRIMARY KEY,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  reason TEXT NOT NULL CHECK (reason IN (
    'worker_result_ready',
    'queued_capacity_wait',
    'publish_retry_ready',
    'stale_attempt_check',
    'manual_operator_request'
  )),
  dedupe_key TEXT NOT NULL,
  work_item_id TEXT REFERENCES work_items(work_item_id) ON DELETE CASCADE,
  task_id TEXT REFERENCES tasks(task_id) ON DELETE CASCADE,
  attempt_id TEXT REFERENCES attempts(attempt_id) ON DELETE SET NULL,
  result_id TEXT REFERENCES worker_results(result_id) ON DELETE CASCADE,
  source_run_id TEXT REFERENCES agent_runs(run_id) ON DELETE SET NULL,
  consumed_run_id TEXT REFERENCES agent_runs(run_id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'consumed', 'expired', 'canceled')),
  not_before_at TEXT NOT NULL,
  expires_at TEXT,
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  UNIQUE(repo_id, reason, dedupe_key)
);
CREATE TABLE work_item_events (
  event_id TEXT PRIMARY KEY,
  work_item_id TEXT NOT NULL REFERENCES work_items(work_item_id) ON DELETE CASCADE,
  event_type TEXT NOT NULL,
  actor_kind TEXT NOT NULL,
  actor_identity TEXT NOT NULL,
  body TEXT NOT NULL DEFAULT '',
  resolves_event_id TEXT REFERENCES work_item_events(event_id) ON DELETE SET NULL,
  idempotency_key TEXT NOT NULL,
  created_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE work_items (
  work_item_id TEXT PRIMARY KEY,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  priority TEXT NOT NULL DEFAULT 'P2' CHECK (priority IN ('P0', 'P1', 'P2', 'P3')),
  origin_type TEXT NOT NULL CHECK (origin_type IN ('web', 'github')),
  origin_source_id TEXT REFERENCES github_sources(source_id) ON DELETE SET NULL,
  routing_mode TEXT NOT NULL DEFAULT 'auto' CHECK (routing_mode IN ('auto', 'manual')),
  requested_worker TEXT,
  workstream_id TEXT REFERENCES workstreams(workstream_id) ON DELETE SET NULL,
  creation_idempotency_key TEXT NOT NULL UNIQUE,
  created_by TEXT NOT NULL,
  activated_at TEXT,
  completed_at TEXT,
  canceled_at TEXT,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  CHECK ((routing_mode = 'auto' AND requested_worker IS NULL)
      OR (routing_mode = 'manual' AND requested_worker IS NOT NULL))
);
CREATE TABLE worker_phases (
  phase_id TEXT PRIMARY KEY,
  attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id) ON DELETE CASCADE,
  phase TEXT NOT NULL CHECK (phase IN ('prepare', 'analyze', 'plan', 'execute', 'verify', 'publish', 'handoff')),
  status TEXT NOT NULL,
  summary TEXT NOT NULL,
  next_step TEXT,
  created_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE worker_results (
  result_id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL REFERENCES tasks(task_id) ON DELETE CASCADE,
  attempt_id TEXT NOT NULL REFERENCES attempts(attempt_id) ON DELETE CASCADE,
  output_type TEXT NOT NULL,
  consumed_event_fingerprints_json TEXT NOT NULL DEFAULT '[]',
  verification_json TEXT NOT NULL DEFAULT '[]',
  handoff TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  UNIQUE(task_id, attempt_id)
);
CREATE TABLE workflow_bindings (
  subject_type TEXT NOT NULL
    CHECK (subject_type IN ('task', 'remediation_episode')),
  subject_id TEXT NOT NULL,
  workflow_kind TEXT NOT NULL
    CHECK (workflow_kind IN ('human_request', 'pr_remediation')),
  owner_engine TEXT NOT NULL
    CHECK (owner_engine IN ('legacy', 'dbos')),
  definition_version TEXT NOT NULL DEFAULT 'v1',
  workflow_id TEXT UNIQUE,
  shadow_workflow_id TEXT UNIQUE,
  binding_status TEXT NOT NULL
    CHECK (binding_status IN ('active', 'terminal', 'attention')),
  recovery_attempts INTEGER NOT NULL DEFAULT 0
    CHECK (recovery_attempts BETWEEN 0 AND 1),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  terminal_at TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  PRIMARY KEY (subject_type, subject_id),
  CHECK ((owner_engine = 'legacy' AND workflow_id IS NULL)
      OR (owner_engine = 'dbos' AND workflow_id IS NOT NULL))
);
CREATE TABLE workflow_outbox (
  signal_id TEXT PRIMARY KEY,
  workflow_id TEXT NOT NULL,
  topic TEXT NOT NULL,
  dedupe_key TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'delivered', 'attention')),
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  not_before_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  delivered_at TEXT,
  last_error_json TEXT,
  UNIQUE (workflow_id, topic, dedupe_key)
);
CREATE TABLE workflow_shadow_observations (
  observation_id TEXT PRIMARY KEY,
  subject_type TEXT NOT NULL,
  subject_id TEXT NOT NULL,
  legacy_decision_json TEXT NOT NULL,
  shadow_decision_json TEXT NOT NULL,
  matched INTEGER NOT NULL CHECK (matched IN (0, 1)),
  mismatch_code TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE workflow_signal_receipts (
  signal_id TEXT PRIMARY KEY,
  workflow_id TEXT NOT NULL,
  topic TEXT NOT NULL,
  consumed_at TEXT NOT NULL
);
CREATE TABLE workstream_sources (
  workstream_id TEXT NOT NULL REFERENCES workstreams(workstream_id) ON DELETE CASCADE,
  source_id TEXT NOT NULL REFERENCES github_sources(source_id) ON DELETE CASCADE,
  relationship TEXT NOT NULL CHECK (relationship IN ('primary', 'derived_pr', 'origin_issue', 'related')),
  created_at TEXT NOT NULL,
  PRIMARY KEY(workstream_id, source_id)
);
CREATE TABLE workstreams (
  workstream_id TEXT PRIMARY KEY,
  repo_id TEXT NOT NULL REFERENCES repos(repo_id) ON DELETE CASCADE,
  primary_source_id TEXT REFERENCES github_sources(source_id) ON DELETE SET NULL,
  origin_workstream_id TEXT REFERENCES workstreams(workstream_id) ON DELETE SET NULL,
  lifecycle TEXT NOT NULL DEFAULT 'active' CHECK (lifecycle IN ('active', 'completed', 'waiting_for_user', 'failed', 'canceled')),
  active_task_id TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  metadata_json TEXT NOT NULL DEFAULT '{}'
);
CREATE INDEX idx_agent_runs_retention
ON agent_runs(status, julianday(finished_at));
CREATE INDEX idx_agent_runs_started
ON agent_runs(started_at DESC, run_id DESC);
CREATE INDEX idx_daemon_events_retention
ON daemon_events(julianday(created_at));
CREATE INDEX idx_daemon_events_run_created
ON daemon_events(daemon_run_id, created_at);
CREATE INDEX idx_daemon_events_type_created
ON daemon_events(event_type, created_at);
CREATE INDEX idx_github_read_cache_expiry ON github_read_cache(expires_at);
CREATE INDEX idx_github_scan_batches_pending
ON github_scan_batches(repo_id,completed_at,retry_at);
CREATE INDEX idx_knowledge_candidates_status
ON knowledge_candidates(repo_id, status, created_at);
CREATE INDEX idx_leases_expired_retention
ON leases(status, julianday(expires_at));
CREATE UNIQUE INDEX idx_leases_one_active_resource
ON leases(resource_type, resource_key)
WHERE status = 'active';
CREATE INDEX idx_leases_owner_status
ON leases(owner_id, status);
CREATE INDEX idx_leases_released_retention
ON leases(status, julianday(released_at));
CREATE INDEX idx_notifications_delivery_pending
ON notifications(channel, status, created_at, notification_id)
WHERE COALESCE(json_extract(metadata_json, '$.delivery.status'), '') NOT IN ('sent', 'exhausted');
CREATE INDEX idx_notifications_delivery_state
ON notifications(json_extract(metadata_json, '$.delivery.status'));
CREATE INDEX idx_pr_ci_observations_episode
ON pr_ci_observations(episode_id, completed_at);
CREATE INDEX idx_pr_remediation_episodes_status
ON pr_remediation_episodes(status, updated_at);
CREATE INDEX idx_project_memory_entries_repo_updated
ON project_memory_entries(repo_id, updated_at);
CREATE INDEX idx_project_memory_revisions_memory
ON project_memory_revisions(memory_id, created_at);
CREATE INDEX idx_project_memory_terms_lookup
ON project_memory_terms(repo_id, term_type, term_value);
CREATE INDEX idx_runtime_knowledge_lookup
ON runtime_knowledge(repo_id, active, scope_type, scope_value);
CREATE INDEX idx_supervision_checkpoints_due
ON supervision_checkpoints(next_check_at, scope_type, scope_id, rule_id)
WHERE next_check_at IS NOT NULL;
CREATE UNIQUE INDEX idx_supervision_incidents_active
ON supervision_incidents(scope_type, scope_id, rule_id, lineage_key)
WHERE status NOT IN ('resolved','dismissed');
CREATE INDEX idx_supervision_incidents_recency
ON supervision_incidents(last_observed_at DESC, incident_id DESC);
CREATE INDEX idx_supervision_incidents_scope_history
ON supervision_incidents(scope_type, scope_id, rule_id, lineage_key, first_observed_at DESC);
CREATE UNIQUE INDEX idx_supervision_recovery_active_scope
ON supervision_recovery_actions(scope_type, scope_id)
WHERE status IN ('requested','applying','observing','unknown');
CREATE INDEX idx_supervision_recovery_budget
ON supervision_recovery_actions(lineage_key, stage_family);
CREATE INDEX idx_supervision_recovery_due
ON supervision_recovery_actions(status, next_check_at);
CREATE INDEX idx_wakeups_consumed_run
ON wakeups(consumed_run_id);
CREATE INDEX idx_wakeups_pending_work_item
        ON wakeups(work_item_id, status, not_before_at)
        WHERE work_item_id IS NOT NULL
        ;
CREATE INDEX idx_wakeups_result
ON wakeups(result_id);
CREATE INDEX idx_wakeups_source_run
ON wakeups(source_run_id);
CREATE INDEX idx_wakeups_status_due
ON wakeups(repo_id, status, not_before_at, created_at);
CREATE UNIQUE INDEX idx_work_item_events_idempotency
ON work_item_events(work_item_id, idempotency_key);
CREATE INDEX idx_work_item_events_resolves
ON work_item_events(resolves_event_id) WHERE resolves_event_id IS NOT NULL;
CREATE INDEX idx_work_item_events_timeline
ON work_item_events(work_item_id, created_at DESC, event_id DESC);
CREATE INDEX idx_work_items_board_order
ON work_items(updated_at DESC, work_item_id DESC);
CREATE UNIQUE INDEX idx_work_items_origin_source
ON work_items(origin_source_id) WHERE origin_source_id IS NOT NULL;
CREATE INDEX idx_work_items_repo_updated
ON work_items(repo_id, updated_at DESC, work_item_id DESC);
CREATE UNIQUE INDEX idx_work_items_workstream
ON work_items(workstream_id) WHERE workstream_id IS NOT NULL;
CREATE INDEX idx_worker_phases_attempt_created
  ON worker_phases(attempt_id, created_at DESC, phase_id DESC);
CREATE INDEX idx_workflow_bindings_active
ON workflow_bindings(owner_engine, subject_type, updated_at)
WHERE binding_status = 'active';
CREATE INDEX idx_workflow_outbox_pending_due
ON workflow_outbox(not_before_at, created_at)
WHERE status = 'pending';
CREATE INDEX idx_workflow_shadow_observations_mismatch
ON workflow_shadow_observations(created_at)
WHERE matched = 0;
CREATE UNIQUE INDEX idx_workstreams_one_active_task
ON tasks(workstream_id)
WHERE lifecycle IN ('detected', 'authorized', 'classified', 'queued', 'running');
CREATE INDEX review_runs_reserved ON review_runs(slot_reserved) WHERE slot_reserved=1;
CREATE INDEX review_sessions_workstream ON review_sessions(workstream_id, created_at);
CREATE INDEX vote_runs_reserved ON vote_runs(slot_reserved) WHERE slot_reserved=1;
CREATE INDEX vote_sessions_workstream ON vote_sessions(workstream_id, created_at);
